import{_ as e,o as i,c as l,a2 as r}from"./chunks/framework.ClgMjOt7.js";const c=JSON.parse('{"title":"よくある質問","description":"Palleriaのインストール、ログイン、画像表示に関するFAQ。","frontmatter":{"title":"よくある質問","description":"Palleriaのインストール、ログイン、画像表示に関するFAQ。"},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1789107345000}'),t={name:"guide/faq.md"};function o(s,a,d,n,h,u){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="よくある質問" tabindex="-1">よくある質問 <a class="header-anchor" href="#よくある質問" aria-label="Permalink to &quot;よくある質問&quot;">​</a></h1><h2 id="palleriaはpixiv公式アプリですか" tabindex="-1">PalleriaはPixiv公式アプリですか？ <a class="header-anchor" href="#palleriaはpixiv公式アプリですか" aria-label="Permalink to &quot;PalleriaはPixiv公式アプリですか？&quot;">​</a></h2><p>いいえ。Palleriaはコミュニティによって開発されているオープンソースの非公式クライアントで、Pixiv Inc.とは関係ありません。</p><h2 id="対応しているandroidバージョンは" tabindex="-1">対応しているAndroidバージョンは？ <a class="header-anchor" href="#対応しているandroidバージョンは" aria-label="Permalink to &quot;対応しているAndroidバージョンは？&quot;">​</a></h2><p>現在のソースコードではAndroid 7.1（API 25）以降を対象としています。端末固有の制限によって、一部機能を利用できない場合があります。</p><h2 id="google-playからインストールできますか" tabindex="-1">Google Playからインストールできますか？ <a class="header-anchor" href="#google-playからインストールできますか" aria-label="Permalink to &quot;Google Playからインストールできますか？&quot;">​</a></h2><p>このドキュメントで案内している配布元は、PalleriaのF-DroidリポジトリとGitHub Releasesです。詳しくは<a href="./install">インストール</a>を参照してください。</p><h2 id="画像が表示されません" tabindex="-1">画像が表示されません <a class="header-anchor" href="#画像が表示されません" aria-label="Permalink to &quot;画像が表示されません&quot;">​</a></h2><p>次の順に確認してください。</p><ol><li>ほかのネットワークへ切り替える</li><li>VPN、独自DNS、広告ブロッカーを確認する</li><li>設定している画像プロキシを確認する</li><li>アプリを最新版へ更新する</li></ol><p>Pixiv側の障害や仕様変更によって、一時的に利用できない場合もあります。</p><h2 id="ログイン情報をissueに書いてもよいですか" tabindex="-1">ログイン情報をIssueに書いてもよいですか？ <a class="header-anchor" href="#ログイン情報をissueに書いてもよいですか" aria-label="Permalink to &quot;ログイン情報をIssueに書いてもよいですか？&quot;">​</a></h2><p>書かないでください。パスワード、Cookie、リフレッシュトークン、個人情報をIssueやログへ含めないでください。問題報告では、アプリのバージョン、Androidのバージョン、再現手順、機密情報を除いたエラー内容を伝えてください。</p><h2 id="不具合や要望はどこへ報告しますか" tabindex="-1">不具合や要望はどこへ報告しますか？ <a class="header-anchor" href="#不具合や要望はどこへ報告しますか" aria-label="Permalink to &quot;不具合や要望はどこへ報告しますか？&quot;">​</a></h2><p><a href="https://github.com/yunfie-twitter/Palleria/issues" target="_blank" rel="noreferrer">GitHub Issues</a>を利用してください。既存のIssueを検索してから、新しいIssueを作成してください。</p>',15)])])}const P=e(t,[["render",o]]);export{c as __pageData,P as default};
